export function mostrarCadastro(e){e.innerHTML='\n        <section class="cadastro">\n            <h2>Cadastro de Voluntário</h2>\n\n            <form id="formularioCadastro">\n\n                <label for="nome">Nome completo:</label>\n                <input type="text" id="nome" name="nome" required>\n\n                <label for="email">E-mail:</label>\n                <input type="email" id="email" name="email" required>\n\n                <label for="nascimento">Data de nascimento:</label>\n                <input type="date" id="nascimento" name="nascimento" required>\n\n                <label for="cpf">CPF:</label>\n                <input type="text" id="cpf" name="cpf" required>\n\n                <label for="telefone">Telefone:</label>\n                <input type="tel" id="telefone" name="telefone" required>\n\n                <label for="endereco">Endereço:</label>\n                <input type="text" id="endereco" name="endereco" required>\n\n                <label for="cidade">Cidade:</label>\n                <input type="text" id="cidade" name="cidade" required>\n\n                <label for="estado">Estado:</label>\n                <select id="estado" name="estado" required>\n                    <option value="">Selecione</option>\n                    <option value="SP">São Paulo</option>\n                    <option value="RJ">Rio de Janeiro</option>\n                    <option value="MG">Minas Gerais</option>\n                </select>\n\n                <label for="cep">CEP:</label>\n                <input type="text" id="cep" name="cep" required>\n\n                <button type="submit">Cadastrar</button>\n            </form>\n        </section>\n    ',configurarFormulario()}function configurarFormulario(){document.getElementById("formularioCadastro").addEventListener("submit",function(e){e.preventDefault();const n=document.getElementById("cpf").value.replace(/\D/g,""),t=document.getElementById("telefone").value.replace(/\D/g,""),o=document.getElementById("cep").value.replace(/\D/g,"");if(11!==n.length)return void mostrarMensagemCadastro("O CPF deve conter 11 números.");if(10!==t.length&&11!==t.length)return void mostrarMensagemCadastro("O telefone deve conter 10 ou 11 números.");if(8!==o.length)return void mostrarMensagemCadastro("O CEP deve conter 8 números.");const a={nome:document.getElementById("nome").value,email:document.getElementById("email").value,nascimento:document.getElementById("nascimento").value,cpf:n,telefone:t,endereco:document.getElementById("endereco").value,cidade:document.getElementById("cidade").value,estado:document.getElementById("estado").value,cep:o},r=JSON.stringify(a);localStorage.setItem("voluntario",r),mostrarMensagemCadastro("Cadastro realizado com sucesso!")})}export function recuperarCadastro(){const e=localStorage.getItem("voluntario");return e?JSON.parse(e):null}function mostrarMensagemCadastro(e){const n=document.getElementById("toast");n&&(n.textContent=e,n.classList.add("mostrar"),setTimeout(()=>{n.classList.remove("mostrar")},3e3))}